content.applied_patch:
--- a/rtl/sequence.sv
+++ b/rtl/sequence.sv
@@ -11,7 +11,7 @@
       case (sel)
          2'b00 : out <= a;
          2'b01 : out <= b;
-         2'b10 : out <= b;
+         2'b10 : out <= c;
          2'b11 : out <= d;
       endcase
    end

--- a/rtl/sequence.sv
+++ b/rtl/sequence.sv
@@ -7,7 +7,7 @@

    // This always block gets executed whenever a/b/c/d/sel changes value
    // When that happens, based on value in sel, output is assigned to either a/b/c/d
-   always @ (a or b or c or d) begin
+   always @ (a or b or c or d or sel) begin
       case (sel)
          2'b00 : out <= a;
          2'b01 : out <= b;

--- a/rtl/sequence.sv
+++ b/rtl/sequence.sv
@@ -10,7 +10,7 @@
    always @ (a or b or c or d or sel) begin
       case (sel)
          2'b00 : out <= a;
-         2'b01 : out <= d;
+         2'b01 : out <= b;
          2'b10 : out <= c;
          2'b11 : out <= d;
       endcase

